// module com.tax.nl
module com.tax.nl {
    requires com.tax.api;
    provides com.tax.api.Tax with com.tax.nl.DutchTax;
}

module com.tax.app {
    requires com.tax.api;
    uses com.tax.api.Tax;
}

ServiceLoader<Tax> loader = ServiceLoader.load(Tax.class);

for (Tax tax : loader) {            // ServiceLoader is Iterable
    System.out.println(tax.rate());
}

Optional<Tax> first = loader.findFirst();

List<Tax> all = loader.stream()     // Stream<ServiceLoader.Provider<Tax>>
        .map(ServiceLoader.Provider::get)
        .toList();
